#!/usr/bin/env python3
"""One full-update trial of the GNN cache-hit CPU key plan.

Reuses the known 81.287322998s best result, no baseline performance rerun.
CPU fingerprint and pytest validate correctness before the only 8-rank update.
"""
from __future__ import annotations
import argparse
import ast
import base64
import csv
from datetime import datetime
import hashlib
import importlib.util
import json
import math
import os
from pathlib import Path
import shutil
import signal
import subprocess
import sys
import time
import traceback
from zipfile import ZipFile, ZIP_DEFLATED

ASSETS = {'candidate_pfn.py': '', 'verify_plan.py': '', 'pfn_bank_hit.diff': '', 'numeric_check.py': '', 'reference_config.json': ''}
OLD_SHA = '49a47378af268c8ce4e0496d5fa862d22596b9215b6dc4ca960687347370ec1d'
NEW_SHA = '90c2ce45a71202ac859ed949d63e120fc30448ba3b418f6a0506bcb4fe235192'
REFERENCE_SECONDS = 81.28732299804688
REFERENCE_RUN = 'patch_gnn_keycache_resume_20261014_195826_483431/benchmark_B1'
CPU_REFERENCE_SHA = '141be2c2287a9dcc90e0c10f95c3a395e6786287bc3d02c178ec3d0b74f4d90d'


def digest(data):
    return hashlib.sha256(data).hexdigest()


def dump(path, value):
    path.write_text(json.dumps(value, indent=2, allow_nan=False)+'\n', encoding='utf-8')


def interrupt_safely(signum, frame):
    raise KeyboardInterrupt('Termination requested; restore the previous source')


def replace_source(target, data):
    if digest(target.read_bytes()) not in (OLD_SHA, NEW_SHA):
        raise RuntimeError('Source changed externally; refusing to overwrite')
    compile(data.decode('utf-8'), str(target), 'exec')
    temp = target.with_name(target.name+f'.bank_hit_{os.getpid()}.tmp')
    try:
        temp.write_bytes(data)
        shutil.copystat(target, temp)
        if os.name == 'posix' and os.geteuid() == 0:
            info = target.stat()
            os.chown(temp, info.st_uid, info.st_gid)
        os.replace(temp, target)
        os.utime(target, None)
    finally:
        if temp.exists():
            temp.unlink()
    if digest(target.read_bytes()) != digest(data):
        raise RuntimeError('Installed source checksum mismatch')


def run(label, command, project, out, threads=1):
    env = os.environ.copy()
    for name in list(env):
        if name.startswith(('PFN_PROFILE', 'PFN_FULL_TRACE', 'PFN_ROLLOUT_TRACE', 'PFN_TORCH_TRACE', 'PFN_UPLOAD_PROBE', 'PFN_HOTSPOT')):
            env.pop(name)
    env.update(PYTHONPATH=str(project), OMP_NUM_THREADS=str(threads), MKL_NUM_THREADS=str(threads),
               OPENBLAS_NUM_THREADS=str(threads), PYTHONUNBUFFERED='1')
    dump(out/(label+'.command.json'), command)
    print('START:', label, flush=True)
    start = time.monotonic()
    with (out/(label+'.log')).open('w', encoding='utf-8') as log:
        proc = subprocess.Popen(command, cwd=project, env=env, stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
        try:
            while True:
                try:
                    code = proc.wait(timeout=30)
                    break
                except subprocess.TimeoutExpired:
                    print('RUNNING:', label, f'{time.monotonic()-start:.0f}s', flush=True)
        except BaseException:
            if proc.poll() is None:
                os.killpg(proc.pid, signal.SIGTERM)
                try:
                    proc.wait(timeout=20)
                except subprocess.TimeoutExpired:
                    os.killpg(proc.pid, signal.SIGKILL)
                    proc.wait()
            raise
    print('FINISHED:', label, 'exit='+str(code), flush=True)
    if code:
        print((out/(label+'.log')).read_text(errors='replace')[-4000:], flush=True)
        raise RuntimeError(label+' failed')


def update_notes(project, out, status):
    target = project/'RELEASE_NOTES.md'
    backup = out/'baseline_RELEASE_NOTES.md'
    shutil.copy2(target, backup)
    old = target.read_bytes()
    entry = (f'\n\n## GNN cache-hit CPU key plan - {datetime.now():%Y-%m-%d}\n\n'
        'The normal inference bank checks its existing identity memo directly for plain owning '
        'read-only NumPy arrays, verifying both weakrefs and re-reading flags on each lookup. '
        'Misses, writable/non-owning inputs and subclasses use the existing content-key routine. '
        'Local bindings and dictionary setdefault preserve first occurrence order while reducing Python calls. '
        'GPU operations, model/PPO definitions, LRU eviction, capacity guards and content-ID semantics are unchanged.\n\n'
        'Validation: 28,736-state key/representative/gather checks, mutation/view/subclass/weakref checks, '
        'exact CPU rollout/PPO/Adam/RNG/restore fingerprint, pytest, and one full 8-rank sequential update.\n\n'
        f"One uninstrumented update: {status['candidate_update_s']:.4f}s; previously confirmed best "
        f"{REFERENCE_SECONDS:.4f}s, training time reduced {status['gain']*100:.2f}%. "
        'Same 8 ranks, 4 CPU threads/rank, 16 environment workers/rank, 245,760 interactions and 480 PPO steps. '
        'This is a single new measurement, compared against the recorded prior best.\n\n'
        f'Experiment/backups: `runs/{out.name}/`. Model SHA256: `{NEW_SHA}`.\n')
    (out/'release_notes_append.txt').write_text(entry, encoding='utf-8')
    new = old+entry.encode('utf-8')
    status['documentation'] = {'path': str(target), 'backup': str(backup),
                              'old_sha256': digest(old), 'new_sha256': digest(new)}
    temp = target.with_name(target.name+f'.bank_hit_{os.getpid()}.tmp')
    try:
        temp.write_bytes(new)
        shutil.copystat(target, temp)
        if os.name == 'posix' and os.geteuid() == 0:
            info = target.stat(); os.chown(temp, info.st_uid, info.st_gid)
        os.replace(temp, target)
    finally:
        if temp.exists(): temp.unlink()


def restore_notes(status):
    if 'documentation' not in status: return
    info = status['documentation']; target = Path(info['path'])
    current = digest(target.read_bytes())
    if current == info['old_sha256']: return
    if current != info['new_sha256']: raise RuntimeError('Release notes changed externally; refusing to overwrite')
    shutil.copy2(info['backup'], target)
    status['documentation_restored'] = True


def pack(out, status):
    dump(out/'trial_status.json', status)
    dest = out/'bank_hit_trial_for_AI.zip'
    files = []
    for pattern in ('*.json','*.log','*.txt','*.diff','*.py','training/config.json','training/runtime*.json',
                    'training/sequential_training.csv','training/sequential_training_cost.json'):
        files.extend(out.glob(pattern))
    with ZipFile(dest,'x',ZIP_DEFLATED,strict_timestamps=False) as z:
        for f in sorted(set(files)):
            if f.is_file() and not f.is_symlink() and f.stat().st_size <= 16*1024*1024:
                z.write(f,f.relative_to(out).as_posix())
    print('REPORT ZIP (Docker):', dest, flush=True)
    print('REPORT ZIP (host):', '/home/mccxadmin/PFN_network_interference_musa_optimized/runs/'+out.name+'/'+dest.name, flush=True)


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--project',type=Path,default=Path('/workspace/PFN_network_interference_musa_optimized'))
    p.add_argument('--dry-run',action='store_true')
    args=p.parse_args(); project=args.project.resolve(); target=project/'pfn_network/models/pfn.py'
    if not target.is_file() or digest(target.read_bytes()) != OLD_SHA:
        p.error('Expected the confirmed GNN content-ID source; no changes made')
    assets={name:base64.b64decode(data,validate=True) for name,data in ASSETS.items()}
    if digest(assets['candidate_pfn.py']) != NEW_SHA:
        p.error('Candidate payload checksum mismatch')
    for name,data in assets.items():
        if name.endswith('.py'): ast.parse(data.decode('utf-8'),filename=name)
    config=json.loads((project/'configs/default.json').read_text(encoding='utf-8'))
    config['meta']=dict(config['meta']); config['sequential_meta']=dict(config.get('sequential_meta',config['meta']))
    for key in ('meta','sequential_meta'): config[key].update(updates=1,validate_every=1,validation_tasks=1)
    if config != json.loads(assets['reference_config.json'].decode('utf-8')):
        p.error('Training configuration differs from the recorded performance reference')
    settings=config['sequential_meta']
    interactions=settings['tasks_per_update']*settings['episodes_per_task']*config['prior']['horizon']
    steps=config['ppo']['epochs']*math.ceil(interactions/config['ppo']['minibatch'])
    if interactions != 245760 or steps != 480:
        p.error('Expected the full default update workload')
    if args.dry_run:
        print('DRY RUN: source/candidate verified. One 8-rank update vs recorded 81.287323s best.'); return
    if importlib.util.find_spec('pytest') is None: p.error('pytest is missing')
    import fcntl
    (project/'logs').mkdir(exist_ok=True)
    with (project/'logs/pretrain.lock').open('a') as lock:
        try: fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError: p.error('Training/profile lock busy; no changes made')
        out=project/'runs'/f'patch_bank_hit_{datetime.now():%Y%m%d_%H%M%S}_{os.getpid()}'
        out.mkdir(parents=True,exist_ok=False); original=target.read_bytes()
        shutil.copy2(target,out/'baseline_pfn.py')
        shutil.copy2(Path(__file__).resolve(),out/'trial_runner.py')
        for name,data in assets.items(): (out/name).write_bytes(data)
        dump(out/'config_one_update.json',config)
        status={'original_sha256':OLD_SHA,'candidate_sha256':NEW_SHA,'reference_update_s':REFERENCE_SECONDS,
                'reference_run':REFERENCE_RUN,'performance_rule':'one candidate update, strictly faster than recorded prior best',
                'nproc':8,'cpu_threads':4,'env_workers':16,'kept':False}
        keep=False
        signal.signal(signal.SIGTERM,interrupt_safely)
        try:
            print('TRIAL DIRECTORY:',out,flush=True)
            run('cpu_key_plan',[sys.executable,str(out/'verify_plan.py')],project,out)
            helper=out/'numeric_check.py'
            reference=project/'runs/patch_gnn_keycache_20261014_193320_483135/candidate_cpu.pt'
            if not reference.is_file() or digest(reference.read_bytes()) != CPU_REFERENCE_SHA:
                reference=out/'previous_cpu.pt'
                run('previous_cpu_fingerprint',[sys.executable,str(helper),'capture','--device','cpu','--output',str(reference)],project,out)
                status['cpu_reference_recreated']=True
            else:
                status['cpu_reference_reused']=True
            replace_source(target,assets['candidate_pfn.py'])
            run('candidate_compile',[sys.executable,'-m','py_compile',str(target)],project,out)
            run('candidate_cpu_fingerprint',[sys.executable,str(helper),'capture','--device','cpu','--output',str(out/'candidate_cpu.pt')],project,out)
            run('cpu_numerical_comparison',[sys.executable,str(helper),'compare','--reference',str(reference),
                 '--candidate',str(out/'candidate_cpu.pt'),'--output',str(out/'cpu_numerical_comparison.json')],project,out)
            run('candidate_pytest',[sys.executable,'-m','pytest','tests','-q'],project,out)
            status['correctness_checks_passed']=True
            destination=out/'training'
            run('candidate_full_update',[sys.executable,'-m','torch.distributed.run','--standalone','--nnodes=1',
                '--nproc-per-node=8','-m','pfn_network.train_eval.run','--device','musa','--stage','train',
                '--objective','sequential','--config',str(out/'config_one_update.json'),'--env-workers','16',
                '--output',str(destination)],project,out,threads=4)
            cost=json.loads((destination/'sequential_training_cost.json').read_text())
            with (destination/'sequential_training.csv').open() as f: rows=list(csv.DictReader(f))
            if cost['total_pretrain_interactions'] != interactions or cost['gradient_steps'] != steps or len(rows) != 1:
                raise RuntimeError('Candidate full-update workload mismatch')
            for rank in range(8):
                info=json.loads((destination/f'runtime_rank{rank}.json').read_text())
                if info['torch_threads'] != 4 or info['world_size'] != 8: raise RuntimeError('Unexpected rank/thread settings')
            row=rows[0]
            if (float(row['treated_count_FC']) != 3.484635416666667 or float(row['treated_count_CD']) != 2.6868245442708334
                    or int(row['max_history_records']) != 384):
                raise RuntimeError('First-update factual rollout/history differs from the confirmed prior run')
            seconds=float(cost['training_seconds'])
            if not math.isfinite(seconds) or seconds <= 0: raise RuntimeError('Invalid update timing')
            keep=seconds < REFERENCE_SECONDS
            status.update(candidate_update_s=seconds,gain=(REFERENCE_SECONDS-seconds)/REFERENCE_SECONDS,
                          full_gpu_update_passed=True,factual_rollout_checks_passed=True)
            if keep: update_notes(project,out,status)
            result=('KEPT' if keep else 'ROLLED BACK')+f': previous_best={REFERENCE_SECONDS:.4f}s candidate={seconds:.4f}s gain={status["gain"]*100:.2f}%'
            (out/'RESULT.txt').write_text(result+'\n',encoding='utf-8'); print(result,flush=True)
        except BaseException:
            keep=False; status['failure']=traceback.format_exc(); print(status['failure'],flush=True)
        finally:
            if not keep:
                try:
                    replace_source(target,original); restore_notes(status); status['restored_previous']=True
                except BaseException:
                    status['restore_error']=traceback.format_exc()
                    print('RESTORE NEEDS ATTENTION:',out/'baseline_pfn.py',flush=True)
            status['kept']=keep; status['final_source_sha256']=digest(target.read_bytes()); pack(out,status)
        if 'failure' in status or 'restore_error' in status: raise SystemExit(2)


if __name__ == '__main__': main()
